    """Enforce the per-hop verdict state-machine and fixed plan/root."""
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == CD_STATUS_CONFLICTED and new_status != CD_STATUS_CONFLICTED:
